  (* [comment removed for export] *)
  Definition qlR_inv (rg : bvmap 5 word) (i : Z) : Prop :=
    getr rg 11 = Z_to_bv 64 (fS + i) /\ getr rg 12 = Z_to_bv 64 lS /\ getr rg 13 = Z_to_bv 64 0 /\ getr rg 10 = Z_to_bv 64 n /\ getr rg 9 = Z_to_bv 64 p /\ getr rg 8 = Z_to_bv 64 s /\ getr rg 2 = Z_to_bv 64 (s - 2128).
  Definition qlR_post (rg : bvmap 5 word) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S;0|21;!1,20!1,2|600;!1+12!1,4|35;!1,4|32;!1,4|31;|30;!1,47|10;!1,49$rg;R!2'@13!2+F!3+<3!2'M#1!3,314vv,6!2'714!2'=2,G!2+F!3+<3!2'M#1!3,315vv,6!2'715!2'=2/n;!2+F!3+<3!2'M#1!3,316vv,6!2'716!2'=2/p;!2+F!3+<3!2'M#1!3,318vv,6!2'718!2'=2/s;!3+<3!2'M#1!3,31:vv,6!2'71:!2'=2!2'C/s;!1,4|;050;").
  Lemma qloopR_run : forall M (q : nat) regs i,
    out_agree M -> (0 < n)%Z -> qlR_inv regs i -> (0 <= i)%Z -> (fS + i + Z.of_nat q + 1 = lS)%Z ->
    exists regs',
